def groupsOfStrings(words):
    ws = words.split(",")
    n = len(ws)
    masks = []
    for w in ws:
        m = 0
        for c in w:
            m |= 1 << (ord(c) - 97)
        masks.append(m)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    first = {}
    for i, m in enumerate(masks):
        if m in first:
            union(i, first[m])
        else:
            first[m] = i
    wild = {}
    for m, i in first.items():
        for b in range(26):
            if m >> b & 1:
                red = m ^ (1 << b)
                if red in first:
                    union(i, first[red])
                if red in wild:
                    union(i, wild[red])
                else:
                    wild[red] = i
    cnt = {}
    for i in range(n):
        r = find(i)
        cnt[r] = cnt.get(r, 0) + 1
    return [len(cnt), max(cnt.values())]
